#include <iostream>
using namespace std;

using int64 = long long;

const int64 MOD = 1000000007;

int64 modPow(int64 base, int64 exponent) {
    int64 result = 1;
    base %= MOD;

    while (exponent > 0) {
        if (exponent & 1)
            result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 p, k;
    cin >> p >> k;

    k %= p;

    if (k == 0) {
        cout << modPow(p, p - 1);
        return 0;
    }

    int64 order = 1;
    int64 current = k;

    while (current != 1) {
        current = static_cast<int64>(
            static_cast<__int128>(current) * k % p
        );
        ++order;
    }

    cout << modPow(p, (p - 1) / order);
    return 0;
}

